<?php use FilamentManager\Core\View; ?>
<div class="toolbar"><div><h1><?= View::t('print_jobs') ?></h1><p class="muted"><?= View::t('print_jobs_help') ?></p></div></div>
<?php if($canEdit): ?><section class="card print-job-import"><h2><?= View::t('import_gcode') ?></h2><form method="post" enctype="multipart/form-data" action="<?= View::e($basePath) ?>/print-jobs/import" class="filter-grid print-job-import-grid"><?= View::csrf() ?><label><?= View::t('printer_name') ?><select name="printer_id" required><option value="">—</option><?php foreach($printers as $printer): ?><option value="<?= View::e($printer['id']) ?>"><?= View::e($printer['name']) ?></option><?php endforeach; ?></select></label><label><?= View::t('gcode_file') ?><input type="file" name="gcode" accept=".gcode,text/plain" required><small><?= View::t('gcode_file_help') ?></small></label><div class="filter-actions"><button><?= View::t('import') ?></button></div></form></section><?php endif; ?>
<section class="card print-job-list"><h2><?= View::t('print_job_history') ?></h2><div class="table-wrap"><table><thead><tr><th><?= View::t('file') ?></th><th><?= View::t('printer_name') ?></th><th><?= View::t('estimated_consumption') ?></th><th><?= View::t('source') ?></th><th><?= View::t('status') ?></th><th><?= View::t('created') ?></th><th></th></tr></thead><tbody><?php foreach($jobs as $job): ?><tr><td><strong><?= View::e($job['source_file_name']) ?></strong></td><td><?= View::e($job['printer_name']) ?></td><td><?= View::e(number_format((float)$job['total_estimated_weight_g'],2,',',' ')) ?> g</td><td><?= View::t('print_source_'.$job['source']) ?></td><td><span class="inventory-status print-job-status-<?= View::e($job['status']) ?>"><?= View::t('print_status_'.$job['status']) ?></span></td><td><?= View::e(View::dateTime($job['created_at'])) ?></td><td><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/print-jobs/<?= View::e($job['id']) ?>"><?= View::t('detail') ?></a></td></tr><?php endforeach; ?><?php if(!$jobs): ?><tr><td colspan="7"><?= View::t('no_print_jobs') ?></td></tr><?php endif; ?></tbody></table></div></section>
